string Arg(string key,string fallback){var a=Environment.GetCommandLineArgs();for(int i=0;i<a.Length-1;i++)if(a[i]==key)return a[i+1];return fallback;}
void Start(){Application.runInBackground=true;server=Arg("--server",server).TrimEnd('/');profile=Arg("--profile","player");int.TryParse(Arg("--agent-port","0"),out agentPort);Application.targetFrameRate=agentPort>0?20:60;var safe=new StringBuilder();foreach(char c in profile)if(char.IsLetterOrDigit(c)||c=='-'||c=='_')safe.Append(c);string rawProfile=profile;string label=Path.GetFileName(rawProfile.TrimEnd('\\','/'));profile=label.Length>32?label.Substring(0,32):label;if(string.IsNullOrEmpty(profile))profile="player";string profileKey;using(var hash=System.Security.Cryptography.SHA256.Create())profileKey=BitConverter.ToString(hash.ComputeHash(Encoding.UTF8.GetBytes(rawProfile))).Replace("-","").Substring(0,24);profileFile=Path.Combine(Application.persistentDataPath,"restaurant-"+profileKey+".json");nickname=profile;try{if(File.Exists(profileFile)){var p=JsonUtility.FromJson<Profile>(File.ReadAllText(profileFile));token=p.token??"";nickname=p.name??profile;shiftId=p.shiftId??"";}}catch{error="Could not restore local profile.";}font=Font.CreateDynamicFontFromOSFont("Arial",64);guiFont=Font.CreateDynamicFontFromOSFont("Segoe UI",18);cream=Mat("Plaster",new Color(.75f,.76f,.63f));dark=Mat("Charcoal",new Color(.12f,.18f,.17f));orange=Mat("Orange",new Color(.92f,.4f,.12f));wood=Mat("Timber",new Color(.4f,.25f,.14f));metal=Mat("Steel",new Color(.48f,.59f,.58f));green=Mat("Sage",new Color(.28f,.44f,.34f));yellow=Mat("Yellow",new Color(.96f,.78f,.24f));BuildBase();StartBridge();if(!string.IsNullOrEmpty(token))StartCoroutine(Connect());StartCoroutine(Poll());}
void Save(){try{File.WriteAllText(profileFile,JsonUtility.ToJson(new Profile{token=token,name=nickname,shiftId=shiftId}));}catch{error="Profile could not be saved; keep this window open.";}}
IEnumerator Http(string route,string json,Action<Reply> ok,Action<string,bool> fail){using(var req=new UnityWebRequest(server+route,json==null?"GET":"POST")){req.downloadHandler=new DownloadHandlerBuffer();if(json!=null){req.uploadHandler=new UploadHandlerRaw(Encoding.UTF8.GetBytes(json));req.SetRequestHeader("Content-Type","application/json");}if(token!="")req.SetRequestHeader("Authorization","Bearer "+token);req.timeout=6;yield return req.SendWebRequest();if(stopped)yield break;Reply r=null;try{r=JsonUtility.FromJson<Reply>(req.downloadHandler.text);}catch{}if(req.result!=UnityWebRequest.Result.Success){fail(r!=null&&r.error!=null?r.error.message:"Connection interrupted. Retry the same request.",req.responseCode>0);yield break;}if(r==null){fail("Unreadable response. Retry the same request.",false);yield break;}ok(r);}}
IEnumerator Connect(){busy=true;yield return Http("/session",("{\"name\":\""+Escape(nickname)+"\""+(string.IsNullOrEmpty(token)?"":",\"token\":\""+Escape(token)+"\"")+"}"),r=>{token=r.token;playerId=r.playerId;connected=true;error="";Save();},(e,d)=>{error=e;connected=false;});busy=false;}
IEnumerator Poll(){while(!stopped){if(connected&&!busy){string requested=shiftId;yield return Http(requested==""?"/lobbies":"/shifts/"+requested,null,r=>{if(requested==shiftId){Apply(r);if(readError&&!busy&&!retry){error="";readError=false;}}},(e,d)=>{if(!busy&&!retry){error=e;readError=true;}});}yield return new WaitForSecondsRealtime(.35f);}}
void Normalize(){if(shift==null)return;if(shift.me!=null&&string.IsNullOrEmpty(shift.me.id))shift.me=null;if(shift.me!=null){if(shift.me.task!=null&&string.IsNullOrEmpty(shift.me.task.kind))shift.me.task=null;if(shift.me.pendingTheft!=null&&shift.me.pendingTheft.readyAt<=0)shift.me.pendingTheft=null;}if(shift.search!=null&&string.IsNullOrEmpty(shift.search.targetId))shift.search=null;if(shift.lastReconciliation!=null&&shift.lastReconciliation.at<=0)shift.lastReconciliation=null;}
void Apply(Reply r){if(r.playerId!=null)playerId=r.playerId;wallet=r.wallet;if(r.lobbies!=null)lobbies=r.lobbies;double t=r.world!=null&&r.world.serverTime>0?r.world.serverTime:r.shift!=null?r.shift.serverTime:0;if(t!=0&&t<snapshotTime)return;if(t!=0){snapshotTime=t;offset=t-DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();}if(r.shift!=null&&!string.IsNullOrEmpty(r.shift.id)){shift=r.shift;shiftId=shift.id;Normalize();}if(r.world!=null&&r.world.map!=null&&r.world.map.version>0){bool rebuild=world==null||world.map==null||r.world.map==null||world.map.version!=r.world.map.version;world=r.world;if(Own!=null)seq=Math.Max(seq,Own.inputSeq);Normalize();if(rebuild)BuildMap();UpdateAvatars();UpdatePublicObjects();}}
void Open(string id){if(busy||retry)return;shiftId=id;shift=null;world=null;snapshotTime=0;walkTarget=null;agentMoving=false;path.Clear();Save();}
string ActionJson(ActionData a){string s="{\"type\":\""+Escape(a.type)+"\"";switch(a.type){case "role":s+=",\"role\":\""+Escape(a.role)+"\"";break;case "ready":s+=",\"ready\":"+a.ready.ToString().ToLowerInvariant();break;case "begin":s+=",\"kind\":\""+Escape(a.kind)+"\"";if(!string.IsNullOrEmpty(a.orderId))s+=",\"orderId\":\""+Escape(a.orderId)+"\"";break;case "step":s+=",\"value\":\""+Escape(a.value)+"\"";break;case "pickup":s+=",\"orderId\":\""+Escape(a.orderId)+"\"";break;case "steal":case "return":s+=",\"amount\":"+a.amount;break;case "recover":s+=",\"dropId\":\""+Escape(a.dropId)+"\"";break;case "search":s+=",\"targetId\":\""+Escape(a.targetId)+"\"";break;}return s+"}";}
void Send(ActionData a){if(!connected||busy||retry)return;walkTarget=null;agentMoving=false;direction=Vector2.zero;StartCoroutine(StopThenSend(a));}
IEnumerator StopThenSend(ActionData a){busy=true;float until=Time.unscaledTime+7;while(inputBusy&&Time.unscaledTime<until)yield return null;if(inputBusy){error="Movement acknowledgement is delayed. Try again after reconnecting.";busy=false;yield break;}bool acknowledged=shift==null||shift.phase!="active"||Self==null||!Self.active;if(!acknowledged)yield return Http("/shifts/"+shiftId+"/input",JsonUtility.ToJson(new InputData{seq=++seq,x=0,z=0}),r=>{Apply(r);acknowledged=true;},(e,d)=>{error=e;});if(!acknowledged){busy=false;yield break;}pendingPath="/shifts/"+shiftId+"/commands";pendingJson=("{\"commandId\":\""+Guid.NewGuid().ToString()+"\",\"action\":"+ActionJson(a)+"}");yield return Mutate();}
void Create(int d){if(!connected||busy||retry)return;pendingPath="/shifts";pendingJson=("{\"commandId\":\""+Guid.NewGuid().ToString()+"\",\"durationSeconds\":"+d+"}");StartCoroutine(Mutate());}
IEnumerator Mutate(){busy=true;error="";readError=false;retry=false;yield return Http(pendingPath,pendingJson,r=>{Apply(r);Save();pendingJson=null;},(e,def)=>{error=e;retry=!def;if(def)pendingJson=null;});busy=false;}
void Update(){Job job;while(jobs.TryDequeue(out job)){try{job.result=Execute(JsonUtility.FromJson<AgentRequest>(job.json));}catch(Exception e){job.result="{\"accepted\":false,\"error\":\""+Escape(e.Message)+"\"}";}completedActionId=job.id;Cache();job.result=job.result.TrimEnd('}')+",\"actionId\":"+job.id+"}";job.done.Set();}BuildControls();if(Input.GetKeyDown(KeyCode.F1))help=!help;if(Input.GetKeyDown(KeyCode.F12))Capture();if(Input.GetKeyDown(KeyCode.E)&&!busy)foreach(var c in controls)if(c.enabled){Activate(c);break;}if(shift!=null&&shift.phase=="active"&&Self!=null&&Self.active&&Own!=null){var d=new Vector2(Input.GetAxisRaw("Horizontal"),Input.GetAxisRaw("Vertical"));if(busy||Self.task!=null||Self.pendingTheft!=null)d=Vector2.zero;if(d.sqrMagnitude>.01f){walkTarget=null;agentMoving=false;}else if(!busy&&Self.task==null&&Self.pendingTheft==null&&walkTarget.HasValue)d=WalkDirection();else if(!busy&&Self.task==null&&Self.pendingTheft==null&&agentMoving)d=direction;if(!busy&&Time.unscaledTime>=nextInput&&!inputBusy){nextInput=Time.unscaledTime+.05f;StartCoroutine(InputTick(Vector2.ClampMagnitude(d,1)));}}Smooth();if(cam!=null&&Own!=null){var p=new Vector3(Own.x,0,Own.z);cam.transform.position=Vector3.Lerp(cam.transform.position,p+new Vector3(0,15,-12),Time.unscaledDeltaTime*5);cam.transform.LookAt(p+Vector3.up*.3f);}Cache();}
