bool Near(string kind,int table=0){if(Own==null||world==null||world.map==null||world.map.stations==null)return false;foreach(var s in world.map.stations)if((s.kind==kind||s.id==kind)&&(table==0||s.table==table)&&(Self==null||string.IsNullOrEmpty(s.zone)||Self.zone==s.zone)&&Vector2.Distance(new Vector2(Own.x,Own.z),new Vector2(s.x,s.z))<=s.radius)return true;return false;}
