void Add(string name,ActionData a,bool enabled=true){controls.Add(new Control{name=name,action=a,enabled=enabled&&!busy&&!retry});}
void BuildControls(){controls.Clear();if(!connected||shift==null)return;var me=Self;if(shift.phase=="waiting"){if(me==null||!me.active)Add("Join shift",new ActionData{type="join"});else{foreach(var r in new[]{"chef","waiter","barman","runner"})Add("Role "+r,new ActionData{type="role",role=r},me.role!=r);Add(me.ready?"Not ready":"Ready up",new ActionData{type="ready",ready=!me.ready});Add("Leave shift",new ActionData{type="leave"});if(shift.hostId==playerId)Add("Start shift",new ActionData{type="start"},ReadyCrew());}return;}if(shift.phase!="active"||me==null||!me.active)return;if(me.task!=null){foreach(var v in me.task.choices??new string[0])Add(v,new ActionData{type="step",value=v},Now>=me.task.nextAt&&Now<me.task.expiresAt);Add("Cancel task",new ActionData{type="cancel"});return;}if(me.pendingTheft!=null){Add("Take noodles",new ActionData{type="take"},Now>=me.pendingTheft.readyAt);Add("Cancel theft",new ActionData{type="cancel"});return;}foreach(var o in shift.orders??new Order[0]){if(o.status!="open")continue;if(me.role=="chef"&&Near("cook")&&!o.foodReady)Add("Cook table "+o.table,new ActionData{type="begin",kind="cook",orderId=o.id},shift.stock>0&&shift.cleanPlates>0);if(me.role=="barman"&&Near("drink")&&!o.drinkReady)Add("Mix table "+o.table,new ActionData{type="begin",kind="drink",orderId=o.id},shift.stock>0);if(me.role=="waiter"&&Own!=null){if(CanPickup(o)&&string.IsNullOrEmpty(Own.carryingOrderId)&&o.foodReady&&o.drinkReady)Add("Pick up table "+o.table,new ActionData{type="pickup",orderId=o.id});if(Own.carryingOrderId==o.id&&Near("serve",o.table))Add("Serve table "+o.table,new ActionData{type="begin",kind="serve",orderId=o.id});}}if(me.role=="waiter"&&Own!=null&&!string.IsNullOrEmpty(Own.carryingOrderId))Add("Put down tray",new ActionData{type="drop"});if(me.role=="runner"&&Near("wash"))Add("Wash plates",new ActionData{type="begin",kind="wash"},shift.dirtyPlates>0);if(me.role=="runner"&&Near("restock"))Add("Restock supplies",new ActionData{type="begin",kind="restock"},shift.stock<=8&&(shift.vault>=2||shift.emergencyRestockAvailable));if(Near("office")){Add("Deposit takings",new ActionData{type="deposit"},me.pouch>0);Add("Reconcile books",new ActionData{type="reconcile"});Add("Prepare theft",new ActionData{type="steal",amount=amount},me.canSteal&&shift.vault>=amount);Add("Return stolen noodles",new ActionData{type="return",amount=amount},me.stolen>=amount);}foreach(var d in shift.drops??new Drop[0])if(d.zone==me.zone)Add("Recover pouch "+d.id,new ActionData{type="recover",dropId=d.id},NearPouch(d.id));foreach(var c in shift.crew??new Crew[0])if(c.active&&c.id!=me.id&&c.zone==me.zone)Add("Search "+c.name,new ActionData{type="search",targetId=c.id},shift.search==null&&Now>=me.searchAvailableAt&&NearPerson(c.id,2));Add("Leave shift",new ActionData{type="leave"});if(shift.search!=null)Add("Support search",new ActionData{type="support"},CanSupport());}
Position Person(string id){if(world!=null)foreach(var p in world.players??new Position[0])if(p.id==id)return p;return null;}
bool NearPerson(string id,float range){var p=Person(id);return Own!=null&&p!=null&&p.active&&Vector2.Distance(new Vector2(Own.x,Own.z),new Vector2(p.x,p.z))<=range;}
bool NearPouch(string id){if(world!=null&&Own!=null)foreach(var p in world.drops??new PouchLocation[0])if(p.dropId==id)return Vector2.Distance(new Vector2(Own.x,Own.z),new Vector2(p.x,p.z))<=1.6f;return false;}
bool CanSupport(){var q=shift.search;if(q==null||Self==null||q.resolvesAt>0||q.targetId==Self.id||Array.IndexOf(q.supporters??new string[0],Self.id)>=0||!NearPerson(q.targetId,2))return false;var target=Person(q.targetId);if(target==null||target.zone!=Self.zone)return false;foreach(var id in q.supporters??new string[0]){var p=Person(id);if(p==null||p.zone!=target.zone||Vector2.Distance(new Vector2(p.x,p.z),new Vector2(target.x,target.z))>2)return false;}return true;}
bool ReadyCrew(){int n=0;var roles=new HashSet<string>();foreach(var c in shift.crew??new Crew[0])if(c.active){n++;if(!c.ready)return false;roles.Add(c.role);}return n>=4&&n<=8&&roles.Count==4;}
