string NameOf(string id){foreach(var c in shift.crew??new Crew[0])if(c.id==id)return c.name;return "crewmate";}
static long Seconds(double ms){return (long)Math.Ceiling(Math.Max(0,ms)/1000);}
static string Clock(double ms){long s=Seconds(ms);return s/60+":"+(s%60).ToString("00");}
Material Mat(string n,Color c){var m=new Material(surfaceShader!=null?surfaceShader:Shader.Find("Standard"));m.name=n;m.color=c;if(m.HasProperty("_Glossiness"))m.SetFloat("_Glossiness",.15f);return m;}
GameObject Box(string n,Vector3 p,Vector3 size,Material m,Transform parent=null){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=n;g.transform.SetParent(parent,false);g.transform.localPosition=p;g.transform.localScale=size;g.GetComponent<Renderer>().sharedMaterial=m;Destroy(g.GetComponent<Collider>());return g;}
void Label(string text,Vector3 p,Transform parent){var g=new GameObject(text);g.transform.SetParent(parent,false);g.transform.localPosition=p;g.transform.localRotation=Quaternion.Euler(90,0,0);var t=g.AddComponent<TextMesh>();t.text=text;t.font=font;t.fontSize=40;t.characterSize=.035f;t.anchor=TextAnchor.MiddleCenter;t.color=new Color(.97f,.9f,.57f);g.GetComponent<MeshRenderer>().sharedMaterial=font.material;}
void BuildBase(){RenderSettings.ambientLight=new Color(.65f,.71f,.69f);var l=new GameObject("Afternoon light").AddComponent<Light>();l.type=LightType.Directional;l.intensity=1.15f;l.shadows=LightShadows.Soft;l.transform.rotation=Quaternion.Euler(48,-25,0);cam=new GameObject("Restaurant camera").AddComponent<Camera>();cam.tag="MainCamera";cam.backgroundColor=new Color(.12f,.2f,.22f);cam.fieldOfView=48;cam.transform.position=new Vector3(0,26,-20);cam.transform.LookAt(new Vector3(0,0,1));var asset=Resources.Load<TextAsset>("restaurant-map");if(asset!=null){world=new World{map=JsonUtility.FromJson<MapView>(asset.text)};BuildMap();}}
void BuildMap(){if(world==null||world.map==null)return;if(geometry!=null)Destroy(geometry.gameObject);geometry=new GameObject("Authoritative restaurant map").transform;Box("Foundation",new Vector3(0,-.25f,1),new Vector3(26,.5f,24),dark,geometry);Box("Dining floor",new Vector3(5,-.01f,-2),new Vector3(14,.03f,16),wood,geometry);Box("Kitchen floor",new Vector3(-7,.005f,0),new Vector3(10,.04f,10),metal,geometry);Box("Back corridor",new Vector3(0,.01f,6),new Vector3(25,.04f,2),green,geometry);for(int x=-11;x<=11;x+=2)for(int z=-9;z<=11;z+=2)Box("Floor joint",new Vector3(x,.035f,z),new Vector3(.025f,.008f,1.95f),dark,geometry);foreach(var o in world.map.obstacles??new Obstacle[0]){bool wall=o.kind=="wall";float height=wall?1.65f:1.05f;Box(wall?"Wall":"Counter",new Vector3(o.x,height/2,o.z),new Vector3(o.w,height,o.d),wall?cream:green,geometry);if(!wall)Box("Countertop",new Vector3(o.x,height+.04f,o.z),new Vector3(o.w+.06f,.08f,o.d+.06f),metal,geometry);}foreach(var s in world.map.stations??new Station[0]){Label(s.kind=="serve"?"TABLE "+s.table:s.kind=="pickup"?"SERVING HATCH":s.kind.ToUpperInvariant(),new Vector3(s.x,.07f,s.z),geometry);var marker=GameObject.CreatePrimitive(PrimitiveType.Cylinder);marker.name="Station "+s.id;marker.transform.SetParent(geometry);marker.transform.position=new Vector3(s.x,.045f,s.z);marker.transform.localScale=new Vector3(.45f,.02f,.45f);marker.GetComponent<Renderer>().sharedMaterial=yellow;Destroy(marker.GetComponent<Collider>());}Label("KITCHEN",new Vector3(-7,.07f,3.5f),geometry);Label("DINING ROOM",new Vector3(6,.07f,3.5f),geometry);Label("WASH-UP",new Vector3(-11,.07f,9),geometry);Label("OFFICE",new Vector3(1,.07f,9),geometry);Label("STOCKROOM",new Vector3(9,.07f,9),geometry);}
Avatar NewAvatar(Position p){var a=new Avatar();a.root=new GameObject("Prisoner "+p.name).transform;Box("Uniform",new Vector3(0,1.05f,0),new Vector3(.6f,.7f,.38f),cream,a.root);for(int i=0;i<4;i++)Box("Prison stripes",new Vector3(0,.81f+i*.16f,-.005f),new Vector3(.61f,.065f,.39f),dark,a.root);var h=GameObject.CreatePrimitive(PrimitiveType.Sphere);h.transform.SetParent(a.root,false);h.transform.localPosition=new Vector3(0,1.63f,0);h.transform.localScale=Vector3.one*.44f;h.GetComponent<Renderer>().sharedMaterial=orange;Destroy(h.GetComponent<Collider>());for(int i=0;i<2;i++){Box("Eye",new Vector3(i==0?-.085f:.085f,1.67f,.205f),new Vector3(.055f,.055f,.035f),dark,a.root);Box("Arm",new Vector3(i==0?-.4f:.4f,1.04f,.15f),new Vector3(.16f,.5f,.18f),cream,a.root);Box("Leg",new Vector3(i==0?-.17f:.17f,.39f,0),new Vector3(.22f,.75f,.26f),dark,a.root);}a.label=new GameObject("Name").AddComponent<TextMesh>();a.label.transform.SetParent(a.root,false);a.label.transform.localPosition=new Vector3(0,2.1f,0);a.label.font=font;a.label.fontSize=40;a.label.characterSize=.08f;a.label.anchor=TextAnchor.MiddleCenter;a.label.color=p.id==playerId?Color.yellow:Color.white;a.label.GetComponent<MeshRenderer>().sharedMaterial=font.material;a.tray=Box("Carried yellow tray",new Vector3(0,1.1f,.55f),new Vector3(.85f,.1f,.58f),yellow,a.root).transform;Box("Bowl",new Vector3(0,.14f,0),new Vector3(.35f,.18f,.35f),cream,a.tray);a.root.position=new Vector3(p.x,0,p.z);return a;}
void UpdateAvatars(){if(world==null||world.players==null)return;var seen=new HashSet<string>();foreach(var p in world.players){if(!p.active)continue;seen.Add(p.id);Avatar a;if(!avatars.TryGetValue(p.id,out a)){a=NewAvatar(p);avatars[p.id]=a;}a.label.text=p.name+"\n"+p.role;a.tray.gameObject.SetActive(!string.IsNullOrEmpty(p.carryingOrderId));}var remove=new List<string>();foreach(var key in avatars.Keys)if(!seen.Contains(key)){Destroy(avatars[key].root.gameObject);remove.Add(key);}foreach(var key in remove)avatars.Remove(key);}
void Smooth(){if(world==null||world.players==null)return;foreach(var p in world.players){Avatar a;if(!avatars.TryGetValue(p.id,out a))continue;Vector3 target=new Vector3(p.x,0,p.z),delta=target-a.root.position;if(delta.magnitude>3)a.root.position=target;else a.root.position=Vector3.Lerp(a.root.position,target,Time.unscaledDeltaTime*18);if(delta.sqrMagnitude>.003f)a.root.rotation=Quaternion.Slerp(a.root.rotation,Quaternion.LookRotation(delta),Time.unscaledDeltaTime*12);if(cam!=null)a.label.transform.rotation=cam.transform.rotation;}}
void UpdatePublicObjects(){if(world==null)return;var seen=new HashSet<string>();if(shift!=null){int index=0;foreach(var o in shift.orders??new Order[0])if(o.status=="open"&&o.foodReady&&o.drinkReady){bool carried=false,placed=false;Vector3 at=Vector3.zero;foreach(var d in world.deliveries??new Delivery[0])if(d.orderId==o.id){if(!string.IsNullOrEmpty(d.carrierId))carried=true;else{at=new Vector3(d.x,.15f,d.z);placed=true;}break;}if(carried)continue;if(!placed&&world.map!=null)foreach(var station in world.map.stations??new Station[0])if(station.kind=="pickup"){at=new Vector3(station.x+(index%3-1)*.7f,1.17f,station.z);break;}index++;string key="meal-"+o.id;seen.Add(key);Transform t;if(!publicObjects.TryGetValue(key,out t)){t=Box("Ready tray table "+o.table,Vector3.zero,new Vector3(.7f,.08f,.48f),yellow).transform;Box("Bowl",new Vector3(0,.17f,0),new Vector3(.32f,.22f,.32f),cream,t);publicObjects[key]=t;}t.position=at;}}foreach(var d in world.drops??new PouchLocation[0]){string key="pouch-"+d.dropId;seen.Add(key);Transform t;if(!publicObjects.TryGetValue(key,out t)){t=Box("Dropped takings pouch",Vector3.zero,new Vector3(.35f,.3f,.25f),orange).transform;publicObjects[key]=t;}t.position=new Vector3(d.x,.16f,d.z);}var remove=new List<string>();foreach(var pair in publicObjects)if(!seen.Contains(pair.Key)){Destroy(pair.Value.gameObject);remove.Add(pair.Key);}foreach(var key in remove)publicObjects.Remove(key);}
bool Free(float x,float z){if(world==null||world.map==null)return false;float r=world.map.radius+.04f;var b=world.map.bounds;if(x<b.xMin+r||x>b.xMax-r||z<b.zMin+r||z>b.zMax-r)return false;foreach(var o in world.map.obstacles??new Obstacle[0])if(x>o.x-o.w/2-r&&x<o.x+o.w/2+r&&z>o.z-o.d/2-r&&z<o.z+o.d/2+r)return false;return true;}
const float Cell=.4f;int Key(int x,int z){return (x+128)*256+z+128;}Vector3 Point(int k){return new Vector3((k/256-128)*Cell,0,(k%256-128)*Cell);}
bool MakePath(float x,float z,float range=.15f){if(Own==null||world==null||world.map==null){error="Join an active shift first.";return false;}path.Clear();pathIndex=0;int first=Key(Mathf.RoundToInt(Own.x/Cell),Mathf.RoundToInt(Own.z/Cell));var open=new List<int>{first};var cost=new Dictionary<int,float>{{first,0}};var from=new Dictionary<int,int>();var closed=new HashSet<int>();int found=-1,iterations=0;Vector3 target=new Vector3(x,0,z);while(open.Count>0&&iterations++<16000){int bestIndex=0;float best=float.MaxValue;for(int i=0;i<open.Count;i++){float score=cost[open[i]]+Vector3.Distance(Point(open[i]),target);if(score<best){best=score;bestIndex=i;}}int current=open[bestIndex];open.RemoveAt(bestIndex);if(!closed.Add(current))continue;Vector3 p=Point(current);if(Vector3.Distance(p,target)<=Mathf.Max(range,.3f)&&Free(p.x,p.z)){found=current;break;}int gx=Mathf.RoundToInt(p.x/Cell),gz=Mathf.RoundToInt(p.z/Cell);for(int dx=-1;dx<=1;dx++)for(int dz=-1;dz<=1;dz++){if(dx==0&&dz==0)continue;float nx=(gx+dx)*Cell,nz=(gz+dz)*Cell;if(!Free(nx,nz)||!Free(p.x,nz)||!Free(nx,p.z))continue;int next=Key(gx+dx,gz+dz);if(closed.Contains(next))continue;float c=cost[current]+Cell*(dx!=0&&dz!=0?1.4142f:1);if(!cost.ContainsKey(next)||c<cost[next]){cost[next]=c;from[next]=current;if(!open.Contains(next))open.Add(next);}}}if(found<0){error="No walkable route. Choose a nearby station or doorway.";walkTarget=null;return false;}var reverse=new List<Vector3>();for(int n=found;n!=first;n=from[n])reverse.Add(Point(n));reverse.Reverse();path=reverse;walkTarget=target;agentMoving=false;error="";return true;}
Vector2 WalkDirection(){if(Own==null){walkTarget=null;return Vector2.zero;}var here=new Vector3(Own.x,0,Own.z);while(pathIndex<path.Count&&Vector3.Distance(here,path[pathIndex])<.17f)pathIndex++;if(pathIndex>=path.Count){walkTarget=null;return Vector2.zero;}var d=path[pathIndex]-here;return Vector2.ClampMagnitude(new Vector2(d.x,d.z)*8,1);}
Station[] Nearby(){var list=new List<Station>();if(world!=null&&world.map!=null&&Own!=null)foreach(var s in world.map.stations??new Station[0])if(Vector2.Distance(new Vector2(Own.x,Own.z),new Vector2(s.x,s.z))<=s.radius)list.Add(s);return list.ToArray();}
void Cache(){var cv=new List<ControlView>();foreach(var c in controls)cv.Add(new ControlView{name=c.name,enabled=c.enabled});if(connected&&shift==null)cv.Add(new ControlView{name="Create shift",enabled=!busy&&!retry});cachedObserve=JsonUtility.ToJson(new Observation{completedActionId=completedActionId,pendingActions=jobs.Count,screen=!connected?"nickname":shift==null?"lobby":shift.phase,profile=profile,playerId=playerId,shiftId=shiftId,wallet=wallet,position=Own,shift=shift,world=world,nearby=Nearby(),controls=cv.ToArray(),error=error,busy=busy,connected=connected,walking=walkTarget.HasValue||agentMoving,screenshotPath=screenshotPath});cachedDiagnostics="{\"profile\":\""+Escape(profile)+"\",\"connected\":"+connected.ToString().ToLowerInvariant()+",\"pendingRetry\":"+retry.ToString().ToLowerInvariant()+",\"inputSeq\":"+seq+",\"waypointsRemaining\":"+Math.Max(0,path.Count-pathIndex)+"}";}
string Execute(AgentRequest r){if(r==null)throw new Exception("Missing action.");if(busy&&r.op!="screenshot"&&r.op!="stop")throw new Exception("Client is busy; observe until the current action finishes.");switch(r.op){case "nickname":if(connected){if((r.value??r.name)==nickname)break;throw new Exception("Choose a fresh --profile to use a different nickname.");}nickname=r.value??r.name;StartCoroutine(Connect());break;case "create":if(r.durationSeconds!=120&&r.durationSeconds!=300&&r.durationSeconds!=600&&r.durationSeconds!=900)throw new Exception("Choose120,300,600or900seconds.");Create(r.durationSeconds);break;case "join":if(string.IsNullOrEmpty(r.id))throw new Exception("Shift id required.");if(shiftId!=r.id||shift==null){Open(r.id);StartCoroutine(JoinAfterLoad(r.id));}else Click("Join shift");break;case "role":Click("Role "+(r.value??r.role));break;case "ready":if(Self!=null&&Self.ready==r.ready)break;Click(r.ready?"Ready up":"Not ready");break;case "start":Click("Start shift");break;case "walkTo":if(!string.IsNullOrEmpty(r.name)){Station found=null;if(world!=null&&world.map!=null)foreach(var s in world.map.stations??new Station[0])if(s.id==r.name||s.kind==r.name||("table"+s.table)==r.name){found=s;break;}if(found==null)throw new Exception("Unknown station.");if(!(found.kind=="pickup"?MakePath(found.x,found.z-1.8f,.25f):MakePath(found.x,found.z,Mathf.Max(.45f,found.radius-.45f))))throw new Exception(error);}else if(!MakePath(r.x,r.z))throw new Exception(error);break;case "move":walkTarget=null;agentMoving=true;direction=Vector2.ClampMagnitude(new Vector2(r.x,r.z),1);break;case "stop":walkTarget=null;agentMoving=false;direction=Vector2.zero;break;case "interact":Click(r.name??r.value);break;case "screenshot":Capture();break;case "amount":amount=Mathf.Clamp(r.amount,1,5);break;case "retry":if(retry&&!busy)StartCoroutine(Mutate());else throw new Exception("No uncertain request.");break;default:throw new Exception("Unsupported client control.");}Cache();return "{\"accepted\":true}";}
void Click(string name){BuildControls();foreach(var c in controls)if(c.name==name){if(!c.enabled)throw new Exception("Control unavailable: "+name);Activate(c);return;}throw new Exception("No nearby visible control named "+name);}
IEnumerator JoinAfterLoad(string id){float until=Time.unscaledTime+8;while(shiftId==id&&shift==null&&Time.unscaledTime<until)yield return null;if(shiftId==id&&shift!=null&&(Self==null||!Self.active)){BuildControls();foreach(var c in controls)if(c.name=="Join shift"&&c.enabled){Activate(c);break;}}}
void Capture(){string dir=Path.Combine(Application.persistentDataPath,"screenshots");Directory.CreateDirectory(dir);screenshotPath=Path.Combine(dir,profile+"-"+DateTime.UtcNow.ToString("yyyyMMdd-HHmmss-fff")+".png");ScreenCapture.CaptureScreenshot(screenshotPath);}
static string Escape(string s){return (s??"").Replace("\\","\\\\").Replace("\"","\\\"").Replace("\n","\\n").Replace("\r","");}
void StartBridge(){if(agentPort<=0)return;try{listener=new HttpListener();listener.Prefixes.Add("http://127.0.0.1:"+agentPort+"/");listener.Start();listenerThread=new Thread(()=>{while(!stopped){HttpListenerContext ctx=null;try{ctx=listener.GetContext();string route=ctx.Request.Url.AbsolutePath,result;int status=200;if(ctx.Request.HttpMethod=="GET"&&(route=="/observe"||route=="/state"))result=cachedObserve;else if(ctx.Request.HttpMethod=="GET"&&route=="/diagnostics")result=cachedDiagnostics;else if(ctx.Request.HttpMethod=="POST"&&(route=="/act"||route=="/action")){using(var reader=new StreamReader(ctx.Request.InputStream)){string json=reader.ReadToEnd();if(json.Length>8192)throw new Exception("Action too large.");var job=new Job{id=Interlocked.Increment(ref nextActionId),json=json};jobs.Enqueue(job);if(job.done.WaitOne(8000)){result=job.result;status=result.Contains("\"accepted\":false")?409:202;}else{result="{\"accepted\":false,\"error\":\"Client queue timed out; observe before retrying.\"}";status=503;}}}else{result="{\"error\":\"Unknown client route\"}";status=404;}byte[] bytes=Encoding.UTF8.GetBytes(result);ctx.Response.StatusCode=status;ctx.Response.ContentType="application/json";ctx.Response.ContentLength64=bytes.Length;ctx.Response.OutputStream.Write(bytes,0,bytes.Length);ctx.Response.Close();}catch(Exception e){if(ctx!=null)try{ctx.Response.StatusCode=400;byte[] bytes=Encoding.UTF8.GetBytes("{\"error\":\""+Escape(e.Message)+"\"}");ctx.Response.OutputStream.Write(bytes,0,bytes.Length);ctx.Response.Close();}catch{}}}});listenerThread.IsBackground=true;listenerThread.Start();}catch(Exception e){error="Agent port unavailable: "+e.Message;}}
void OnApplicationQuit(){stopped=true;try{listener?.Stop();listener?.Close();}catch{}if(listenerThread!=null)listenerThread.Join(200);}
}
